import { randomUUID } from 'node:crypto';

const MAX_PROMOS_PER_DAY = 3;
const MIN_PROMO_GAP_MS = 2 * 60 * 60 * 1000;
// A local day is at most 25 hours long, and the gap rule needs 2 hours, so
// anything older than this can never affect a decision.
const RETENTION_MS = 48 * 60 * 60 * 1000;

const formatters = new Map();

function dayKey(ms, timeZone) {
  let fmt = formatters.get(timeZone);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
    formatters.set(timeZone, fmt);
  }
  return fmt.format(ms);
}

export function createGate() {
  // userId -> { sends: [{ id, ms }], newest: number }
  const promosByUser = new Map();
  // id -> userId, only for promos still counted
  const owners = new Map();

  const deny = (rule) => ({ allowed: false, rule, id: null });

  function request({ userId, timeZone, category, now }) {
    if (category === 'security') {
      // Security alerts are never limited and never counted against promos.
      return { allowed: true, rule: '', id: randomUUID() };
    }
    if (category !== 'promo') return deny('invalid-category');

    const ms = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(ms)) return deny('invalid-time');

    let today;
    try {
      today = dayKey(ms, timeZone);
    } catch {
      return deny('invalid-time-zone');
    }

    let entry = promosByUser.get(userId);
    if (!entry) {
      entry = { sends: [], newest: ms };
      promosByUser.set(userId, entry);
    }
    if (ms > entry.newest) entry.newest = ms;

    // Drop sends too old to matter.
    const cutoff = entry.newest - RETENTION_MS;
    if (entry.sends.some((s) => s.ms < cutoff)) {
      entry.sends = entry.sends.filter((s) => {
        if (s.ms >= cutoff) return true;
        owners.delete(s.id);
        return false;
      });
    }

    let sameDay = 0;
    let tooClose = false;
    for (const s of entry.sends) {
      if (Math.abs(ms - s.ms) < MIN_PROMO_GAP_MS) tooClose = true;
      if (dayKey(s.ms, timeZone) === today) sameDay++;
    }
    if (sameDay >= MAX_PROMOS_PER_DAY) return deny('daily-cap');
    if (tooClose) return deny('min-gap');

    // Allowed means the caller sends now, so record it immediately.
    const id = randomUUID();
    entry.sends.push({ id, ms });
    owners.set(id, userId);
    return { allowed: true, rule: '', id };
  }

  function cancel(id) {
    const userId = owners.get(id);
    if (userId === undefined) return;
    owners.delete(id);
    const entry = promosByUser.get(userId);
    if (entry) entry.sends = entry.sends.filter((s) => s.id !== id);
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/courier-inv-d2-1/bot.mjs';

const d = (s) => new Date(s);
const LA = 'America/Los_Angeles';
const req = (g, o) => g.request({ userId: 'u', timeZone: LA, category: 'promo', ...o });

// LA is UTC-7 in July: local midnight = 07:00Z.
{
  const g = createGate();
  const a = req(g, { now: d('2025-07-01T07:00:00Z') });
  assert.equal(a.allowed, true); assert.equal(a.rule, ''); assert.ok(a.id);
  assert.equal(req(g, { now: d('2025-07-01T08:59:59Z') }).rule, 'min-gap');
  assert.equal(req(g, { now: d('2025-07-01T09:00:00Z') }).allowed, true);
  assert.equal(req(g, { now: d('2025-07-01T11:00:00Z') }).allowed, true);
  const r = req(g, { now: d('2025-07-01T13:00:00Z') });
  assert.deepEqual(r, { allowed: false, rule: 'daily-cap', id: null });
  // 06:59Z Jul 2 is still Jul 1 in LA -> capped; 07:00Z is the next day.
  assert.equal(req(g, { now: d('2025-07-02T06:59:00Z') }).rule, 'daily-cap');
  assert.equal(req(g, { now: d('2025-07-02T07:00:00Z') }).allowed, true);
}
// Same instants, other time zone: Berlin (UTC+2) day boundary differs.
{
  const g = createGate();
  const b = (now) => g.request({ userId: 'u', timeZone: 'Europe/Berlin', category: 'promo', now: d(now) });
  assert.equal(b('2025-07-01T21:00:00Z').allowed, true); // 23:00 local
  assert.equal(b('2025-07-01T23:00:00Z').allowed, true); // 01:00 next day
  assert.equal(b('2025-07-02T01:00:00Z').allowed, true);
  assert.equal(b('2025-07-02T03:00:00Z').allowed, true); // 3rd on Jul 2
  assert.equal(b('2025-07-02T05:00:00Z').rule, 'daily-cap');
}
// Cancel frees capacity and gap; unknown/double cancel harmless.
{
  const g = createGate();
  const a = req(g, { now: d('2025-07-01T10:00:00Z') });
  assert.equal(req(g, { now: d('2025-07-01T10:30:00Z') }).rule, 'min-gap');
  g.cancel(a.id); g.cancel(a.id); g.cancel('nope');
  assert.equal(req(g, { now: d('2025-07-01T10:30:00Z') }).allowed, true);
}
// Users independent; security unlimited and not counted.
{
  const g = createGate();
  const now = d('2025-07-01T10:00:00Z');
  for (let i = 0; i < 10; i++) assert.equal(g.request({ userId: 'u', timeZone: LA, category: 'security', now }).allowed, true);
  assert.equal(req(g, { now }).allowed, true);
  assert.equal(g.request({ userId: 'v', timeZone: LA, category: 'promo', now }).allowed, true);
  assert.equal(g.request({ userId: 'u', timeZone: 'bogus', category: 'promo', now }).rule, 'invalid-time-zone');
}
